from taf.ul.ettf.utils.functions import initialize_default
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes
from abc import ABCMeta, abstractmethod
from future.utils import with_metaclass
from collections import namedtuple
import xml.etree.ElementTree as et
import re


class MessageType(object):
    @property
    def name(self):
        return self._name

    @property
    def name_prefixes(self):
        return self._name_prefixes


class LteRrc(MessageType):
    def __init__(self):
        self._name = 'lte_rrc'
        self._name_prefixes = ['lte-rrc', 'nr-rrc']


class X2ap(MessageType):
    def __init__(self):
        self._name = 'x2ap'
        self._name_prefixes = ['x2ap', 'nr-rrc']


class S1ap(MessageType):
    def __init__(self):
        self._name = 's1ap'
        self._name_prefixes = ['s1ap', 'nr-rrc']


class PdmlParserError(LibraryError):
    def __init__(self, msg):
        super(PdmlParserError, self).__init__(exception_causes.PARSING_ERROR, msg)


def name(field):
    return get_attribute(field, 'name')


def showname(field):
    return get_attribute(field, 'showname')


def show(field):
    return get_attribute(field, 'show')


def get_attribute(field, attribute):
    attribute_value = field.attrib.get(attribute)
    if attribute_value is None:
        raise PdmlParserError('Attribute {} of field {} should exist'.format(attribute, field))
    return attribute_value


class Enum(dict):
    def __init__(self, name, value):
        super(Enum, self).__init__()
        self.name = name
        self.value = int(value)

    def __eq__(self, obj):
        if isinstance(obj, int):
            return obj == self.value

        elif isinstance(obj, str):
            return obj == '{} ({})'.format(self.name, self.value) or obj == self.name

        elif isinstance(obj, Enum):
            return obj.name == self.name and obj.value == self.value

        return False

    def __repr__(self):
        return 'Enum {} ({})'.format(self.name, self.value)

    def __ne__(self, obj):
        return not self.__eq__(obj)


class Timestamp(object):
    def __init__(self, timestamp):
        self._timestamp = tuple(timestamp.replace('.', ':').split(':'))

    def __eq__(self, other_timestamp):
        return self._timestamp == other_timestamp

    def __ne__(self, other_timestamp):
        return not self._timestamp == other_timestamp

    def __gt__(self, other_timestamp):
        return self._timestamp > other_timestamp

    def __ge__(self, other_timestamp):
        return self._timestamp >= other_timestamp

    def __lt__(self, other_timestamp):
        return self._timestamp < other_timestamp

    def __le__(self, other_timestamp):
        return self._timestamp <= other_timestamp

    def __repr__(self):
        return '{}:{}:{}.{}'.format(self._timestamp[0], self._timestamp[1], self._timestamp[2], self._timestamp[3])


class AdditionalDataHandler(with_metaclass(ABCMeta, object)):
    @abstractmethod
    def parse(self, raw_message):
        pass


IphyDataElement = namedtuple('IphyDataElement', ['field', 'field_name', 'showname_prefix'])


class IphyData(AdditionalDataHandler):
    def __init__(self):
        self.ue_id = None
        self.enb_id = None
        self.cell_id = None

    def parse(self, raw_message):
        data = raw_message.findall('proto')
        iphy_part = [msg_part for msg_part in data if name(msg_part) == 'iphy']

        if iphy_part:
            for field in list(iphy_part[0]):
                if not self.ue_id:
                    self.ue_id = self._try_to_parse(IphyDataElement(field, 'ue_id', 'UE Id'))

                if not self.enb_id:
                    self.enb_id = self._try_to_parse(IphyDataElement(field, 'enb_id', 'eNodeB ID'))

                if not self.cell_id:
                    self.cell_id = self._try_to_parse(IphyDataElement(field, 'cell_id', 'Cell ID'))

    def _try_to_parse(self, data_element):
        if name(data_element.field) == 'iphy.{}'.format(data_element.field_name):
            regex = re.compile('{prefix}: ({number})'.format(prefix=data_element.showname_prefix, number='[0-9]+'))
            parsed = regex.match(showname(data_element.field))

            if parsed:
                return int(parsed.group(1).strip())
        return None


class Message(dict):
    def __init__(self, message, timestamp):
        super(Message, self).__init__(message)
        self.timestamp = timestamp
        self._additional_data_handlers = {}

    def append_additional_data_handler(self, data_class):
        if not self.has_additional_data(data_class):
            self._additional_data_handlers[data_class] = data_class()
        else:
            raise PdmlParserError('{} was already added'.format(data_class.__name__))

    def additional_data(self, data_class):
        return self._additional_data_handlers.get(data_class, None)

    def has_additional_data(self, data_class):
        return data_class in list(self._additional_data_handlers.keys())

    def parse_additional_data(self, raw_message):
        for handler in list(self._additional_data_handlers.values()):
            handler.parse(raw_message)


class PdmlParser(object):
    def __init__(self):
        self.supported_messages = [LteRrc(), S1ap(), X2ap()]
        self.supported_message_names = [msg.name for msg in self.supported_messages]
        self.supported_message_name_prefixes = []
        for msg in self.supported_messages:
            self.supported_message_name_prefixes.extend(msg.name_prefixes)

    def parse(self, pdmlstring, additional_data_handlers=None):
        parsed_messages = []
        additional_data_handlers = initialize_default(additional_data_handlers, [])
        packets = self._extract_packets(pdmlstring)

        for packet in packets:
            raw_message, timestamp = self._extract_message(packet)
            parsed_message = self._parse_single_message(raw_message)
            parsed_timestamp = self._parse_timestamp(timestamp)

            if parsed_message and parsed_timestamp:
                msg = Message(parsed_message, Timestamp(parsed_timestamp))

                for data_handler in additional_data_handlers:
                    msg.append_additional_data_handler(data_handler)
                msg.parse_additional_data(packet)

                parsed_messages.append(msg)

        return parsed_messages

    def _extract_message(self, packet):
        data = packet.findall('proto')
        filtered_message_parts = [message for message in data if self._name_is_supported(message)]
        filtered_timestamp_parts = [message for message in data if self._has_timestamp(message)]
        assert len(filtered_message_parts) == 1
        assert len(filtered_timestamp_parts) == 1
        return (filtered_message_parts[0], filtered_timestamp_parts[0])

    def _name_is_supported(self, message):
        return name(message) in self.supported_message_names

    @staticmethod
    def _has_timestamp(message):
        return name(message) == 'geninfo'

    @staticmethod
    def _extract_packets(pdmlstring):
        pdml = et.fromstring(pdmlstring)
        return pdml.findall('packet')

    def _parse_single_message(self, message):

        parsed_message = {}
        fields = self._extract_subfields(message)

        for field in fields:
            parsed_message.update(self._parse_single_field(field))

        return parsed_message

    def _parse_single_field(self, field):
        if self._has_no_subfields(field):
            return {self._extract_name(field): TypeConverter().convert(self._extract_value(field))}

        elif self._is_list(field):
            return {self._extract_name(field): self._extract_list(field)}

        parsed_field = {}
        fields = self._extract_subfields(field)

        for f in fields:
            parsed_field.update(self._parse_single_field(f))

        return {self._extract_name(field): parsed_field}

    def _parse_timestamp(self, timestamp):
        timestamp_subfield = self._extract_timestamp_subfields(timestamp)[0]
        timestamp_regex = re.compile(r'{month}\s+{day}, {year} ({hour}:{minute}:{second}.{milisecond}){rest}'.format(
            month='[a-zA-Z]+', day='[0-9]+', year='[0-9]{4}', hour='[0-9]{2}', minute='[0-9]{2}', second='[0-9]{2}', milisecond='[0-9]+', rest='.*'))
        parsed_timestamp = timestamp_regex.match(show(timestamp_subfield))

        if parsed_timestamp:
            return parsed_timestamp.group(1).strip()

        raise PdmlParserError('Timestamp cannot be parsed! {}'.format(show(timestamp)))

    def _extract_subfields(self, field):
        return [f for f in list(field) if self._should_be_parsed(f)]

    def _extract_timestamp_subfields(self, field):
        return [f for f in list(field) if self._is_timestamp_subfield(f)]

    def _should_be_parsed(self, field):
        for name_prefix in self.supported_message_name_prefixes:
            if name(field).startswith(name_prefix):
                return True
        return False

    @staticmethod
    def _is_timestamp_subfield(field):
        if name(field) == 'timestamp':
            return True
        return False

    @staticmethod
    def _is_list(field):
        list_regex = re.compile('{name}: ({number}) item(s)?'.format(name='.*', number='[0-9]+'))
        return list_regex.match(showname(field))

    @staticmethod
    def _has_no_subfields(field):
        return len(field) == 0

    def _extract_list(self, field):
        extracted_list = []

        for list_item in list(field):
            for child in self._extract_subfields(list_item):
                extracted_list.append(self._parse_single_field(child))

        return extracted_list

    @staticmethod
    def _extract_value(field):
        enum_regex = re.compile(r'{name}[:|=] ({value}) \(({num})\)'.format(name='.*', value=r'[a-zA-Z0-9\.\s_-]*', num='[0-9]+'))
        parsed_enum = enum_regex.match(showname(field))

        if parsed_enum:
            return Enum(*(parsed_enum.groups()))

        value_regex = re.compile(r'{name}[:|=] ({value})({rest})?'.format(name='.*', value=r'[a-zA-Z0-9\.\s_-]*', rest=r'\s\(.*\)'))
        parsed_value = value_regex.match(showname(field))

        if parsed_value:
            return parsed_value.group(1).strip()

        return ''

    def _extract_name(self, field):
        field_name = name(field)
        if field_name in self.supported_message_name_prefixes:
            return field_name

        name_regex = re.compile(r'{prefix}{dot}({name})(_element)?'.format(prefix='.*', dot=r'\.', name='.*'))
        parsed_name = name_regex.match(field_name).group(1)
        parsed_name = parsed_name if not parsed_name.endswith('_element') else parsed_name.split('_element')[0]
        return parsed_name.replace('_', '-')


class TypeConverter(object):
    CONVERSIONS = {
        'null': None,
        'true': True,
        'false': False}

    try:
        NUM_TYPES = [int, int]
    except NameError:
        NUM_TYPES = [int]

    def convert(self, value):
        if isinstance(value, Enum):
            return value

        if value.lower() in list(self.CONVERSIONS.keys()):
            return self.CONVERSIONS[value.lower()]

        for num_type in self.NUM_TYPES:
            try:
                return num_type(value)
            except ValueError:
                pass

        return value
